export type AnimationSequenceKind =
  | 'idle'
  | 'walk'
  | 'walk-back'
  | 'dash'
  | 'dash-back'
  | 'jump'
  | 'landing'
  | 'crouch-heavy-kick'
  | 'crouch-medium-kick'
  | 'crouch-light-kick'
  | 'crouch-heavy'
  | 'crouch-medium'
  | 'crouch-light'
  | 'crouch'
  | 'stand-heavy-kick'
  | 'stand-medium-kick'
  | 'stand-light-kick'
  | 'stand-medium'
  | 'stand-light'
  | 'stand-heavy'
  | 'hit'
  | 'guard'
  | 'parry'
  | 'yoroi-doroshi'
  | 'tensei-ranka'
  | 'kikosho'
  | 'hadoken'
  | 'shoryuken'
  | 'tatsumaki'
  | 'super-rush';

export type AnimationTimingCurve = 'linear' | 'ease-in' | 'ease-out' | 'snap' | 'hold';

export interface AnimationFrameEvent {
  frame: number;
  type: 'whoosh' | 'contact' | 'projectile' | 'trail' | 'recovery';
  label?: string;
}

export interface AnimationSequencePhase {
  startupEnd?: number;
  activeStart?: number;
  activeEnd?: number;
  recoveryStart?: number;
}

export interface AnimationSequence {
  id: string;
  characterId: string;
  kind: AnimationSequenceKind;
  asset: string;
  frameCount: number;
  frameWidth: number;
  frameHeight: number;
  fps: number;
  loop: boolean;
  timing: AnimationTimingCurve;
  footLock?: boolean;
  facingRelativeDirection?: 'forward' | 'backward';
  phase?: AnimationSequencePhase;
  events?: readonly AnimationFrameEvent[];
  enabled: boolean;
  renderMode: 'full' | 'bridge';
  poseAuthored: boolean;
  quality: 'hq';
  source: 'approved-hq-pilot' | 'authored-hq';
}

